INSERT INTO message (ROWID, guid, text, handle_id, country, service, date, date_read, date_delivered, is_delivered, is_from_me, is_sent, is_read, is_forward, cache_has_attachments)
VALUES
  (1, 'GUID-MSG-0001', 'Are you still coming to the trail run?', 1, 'US', 'iMessage', 738936000000000000, NULL, 738936600000000000, 1, 0, 1, 0, 0, 0),
  (2, 'GUID-MSG-0002', 'I''ll be there, bringing the map.', 0, 'US', 'iMessage', 738939600000000000, 738940800000000000, 738940200000000000, 1, 1, 1, 1, 0, 1),
  (3, 'GUID-MSG-0003', 'Bring water and the topo.', 2, 'US', 'iMessage', 738943200000000000, NULL, 738943800000000000, 1, 0, 1, 0, 0, 0),
  (4, 'GUID-MSG-0004', 'Route looks fine on my end.', 11, 'US', 'iMessage', 738946800000000000, 738948000000000000, 738947400000000000, 1, 0, 1, 1, 0, 0),
  (5, 'GUID-MSG-0005', 'Copy that, see you at the trailhead.', 0, 'US', 'iMessage', 738950400000000000, NULL, 738951000000000000, 1, 1, 1, 0, 0, 0),
  (6, 'GUID-MSG-0006', 'Keeping the pace easy today.', 3, 'US', 'iMessage', 738954000000000000, 738955200000000000, 738954600000000000, 1, 0, 1, 1, 0, 0),
  (7, 'GUID-MSG-0007', 'Did the deploy land on the staging branch?', 4, 'US', 'iMessage', 738957600000000000, NULL, 738958200000000000, 1, 0, 1, 0, 0, 0),
  (8, 'GUID-MSG-0008', 'Yes, the build is green.', 0, 'US', 'iMessage', 738961200000000000, 738962400000000000, 738961800000000000, 1, 1, 1, 1, 0, 0),
  (9, 'GUID-MSG-0009', 'The montage of the results is attached.', 5, 'US', 'iMessage', 738964800000000000, NULL, 738965400000000000, 1, 0, 1, 0, 0, 1),
  (10, 'GUID-MSG-0010', 'Please review the config before release.', 12, 'US', 'iMessage', 738968400000000000, 738969600000000000, 738969000000000000, 1, 0, 1, 1, 0, 0),
  (11, 'GUID-MSG-0011', 'Tests pass locally, sending logs now.', 6, 'US', 'iMessage', 738972000000000000, NULL, 738972600000000000, 1, 0, 1, 0, 0, 0),
  (12, 'GUID-MSG-0012', 'Merging once approvals come in.', 0, 'US', 'iMessage', 738975600000000000, 738976800000000000, 738976200000000000, 1, 1, 1, 1, 0, 0),
  (13, 'GUID-MSG-0013', 'Hey, are you available this afternoon?', 0, 'US', 'iMessage', 738979200000000000, NULL, 738979800000000000, 1, 1, 1, 0, 0, 0),
  (14, 'GUID-MSG-0014', 'Working late, will send the notes tonight.', 1, 'US', 'iMessage', 738982800000000000, 738984000000000000, 738983400000000000, 1, 0, 1, 1, 0, 0),
  (15, 'GUID-MSG-0015', 'Can you pick up groceries on the way back?', 0, 'US', 'iMessage', 738986400000000000, NULL, 738987000000000000, 1, 1, 1, 0, 0, 0),
  (16, 'GUID-MSG-0016', 'Thanks, that worked for me.', 1, 'US', 'iMessage', 738990000000000000, 738991200000000000, 738990600000000000, 1, 0, 1, 1, 0, 0),
  (17, 'GUID-MSG-0017', 'The lease is up, let me know if that is fine.', 2, 'US', 'iMessage', 738993600000000000, NULL, 738994200000000000, 1, 0, 1, 0, 0, 0),
  (18, 'GUID-MSG-0018', 'Running late, call when you land.', 0, 'US', 'iMessage', 738997200000000000, 738998400000000000, 738997800000000000, 1, 1, 1, 1, 0, 0),
  (19, 'GUID-MSG-0019', 'The deck is attached, page 12 needs edits.', 2, 'US', 'iMessage', 739000800000000000, NULL, 739001400000000000, 1, 0, 1, 0, 0, 0),
  (20, 'GUID-MSG-0020', 'Quiet on the call, keep it short.', 0, 'US', 'iMessage', 739004400000000000, 739005600000000000, 739005000000000000, 1, 1, 1, 1, 0, 0),
  (21, 'GUID-MSG-0021', 'Did the invoice get approved by the vendor?', 0, 'US', 'iMessage', 739008000000000000, NULL, 739008600000000000, 1, 1, 1, 0, 0, 0),
  (22, 'GUID-MSG-0022', 'Send the address, I will park nearby.', 3, 'US', 'iMessage', 739011600000000000, 739012800000000000, 739012200000000000, 1, 0, 1, 1, 0, 0),
  (23, 'GUID-MSG-0023', 'The flight was delayed, still at the gate.', 0, 'US', 'iMessage', 739015200000000000, NULL, 739015800000000000, 1, 1, 1, 0, 0, 0),
  (24, 'GUID-MSG-0024', 'Forwarded: the old thread about the lease.', 3, 'US', 'iMessage', 739018800000000000, 739020000000000000, 739019400000000000, 1, 0, 1, 1, 0, 0),
  (25, 'GUID-MSG-0025', 'Can you confirm the door code for tonight?', 4, 'US', 'iMessage', 739022400000000000, NULL, 739023000000000000, 1, 0, 1, 0, 0, 0),
  (26, 'GUID-MSG-0026', 'The security photo is attached for review.', 0, 'US', 'iMessage', 739026000000000000, 739027200000000000, 739026600000000000, 1, 1, 1, 1, 0, 1),
  (27, 'GUID-MSG-0027', 'Will call back in ten minutes.', 4, 'US', 'iMessage', 739029600000000000, NULL, 739030200000000000, 1, 0, 1, 0, 0, 0),
  (28, 'GUID-MSG-0028', 'The backup generator is running.', 0, 'US', 'iMessage', 739033200000000000, 739034400000000000, 739033800000000000, 1, 1, 1, 1, 0, 0),
  (29, 'GUID-MSG-0029', 'Please keep the volume down in the hall.', 5, 'US', 'iMessage', 739036800000000000, NULL, 739037400000000000, 1, 0, 1, 0, 0, 0),
  (30, 'GUID-MSG-0030', 'The schedule moved to Thursday, noted.', 0, 'US', 'iMessage', 739040400000000000, 739041600000000000, 739041000000000000, 1, 1, 1, 1, 0, 0),
  (31, 'GUID-MSG-0031', 'Any word on the permit for the fence?', 6, 'US', 'iMessage', 739044000000000000, NULL, 739044600000000000, 1, 0, 1, 0, 0, 0),
  (32, 'GUID-MSG-0032', 'The draft is done, sending it now.', 0, 'US', 'iMessage', 739047600000000000, 739048800000000000, 739048200000000000, 1, 1, 1, 1, 1, 0),
  (33, 'GUID-MSG-0033', 'The quote looks too high, check please.', 6, 'US', 'iMessage', 739051200000000000, NULL, 739051800000000000, 1, 0, 1, 0, 0, 0),
  (34, 'GUID-MSG-0034', 'Can you review the lease terms tonight?', 0, 'US', 'iMessage', 739054800000000000, 739056000000000000, 739055400000000000, 1, 1, 1, 1, 0, 0),
  (35, 'GUID-MSG-0035', 'The meter reading is attached below.', 7, 'US', 'iMessage', 739058400000000000, NULL, 739059000000000000, 1, 0, 1, 0, 0, 0),
  (36, 'GUID-MSG-0036', 'Noted, will follow up tomorrow.', 0, 'US', 'iMessage', 739062000000000000, 739063200000000000, 739062600000000000, 1, 1, 1, 1, 0, 0),
  (37, 'GUID-MSG-0037', 'The crew starts at six, be ready.', 8, 'US', 'iMessage', 739065600000000000, NULL, 739066200000000000, 1, 0, 1, 0, 0, 0),
  (38, 'GUID-MSG-0038', 'Did the permit get approved by the city?', 0, 'US', 'iMessage', 739069200000000000, 739070400000000000, 739069800000000000, 1, 1, 1, 1, 0, 0),
  (39, 'GUID-MSG-0039', 'The fence quote looks steep.', 8, 'US', 'iMessage', 739072800000000000, NULL, 739073400000000000, 1, 0, 1, 0, 0, 0),
  (40, 'GUID-MSG-0040', 'Send the revised estimate tonight.', 0, 'US', 'iMessage', 739076400000000000, 739077600000000000, 739077000000000000, 1, 1, 1, 1, 0, 0),
  (41, 'GUID-MSG-0041', 'The gate code changed, use the new one.', 9, 'US', 'iMessage', 739080000000000000, NULL, 739080600000000000, 1, 0, 1, 0, 0, 0),
  (42, 'GUID-MSG-0042', 'Please confirm before the crew arrives.', 0, 'US', 'iMessage', 739083600000000000, 739084800000000000, 739084200000000000, 1, 1, 1, 1, 0, 0),
  (43, 'GUID-MSG-0043', 'The trailer is parked by the side lot.', 10, 'US', 'iMessage', 739087200000000000, NULL, 739087800000000000, 1, 0, 1, 0, 0, 0),
  (44, 'GUID-MSG-0044', 'Call me when the load arrives.', 0, 'US', 'iMessage', 739090800000000000, 739092000000000000, 739091400000000000, 1, 1, 1, 1, 0, 0),
  (45, 'GUID-MSG-0045', 'The permit office closed early today.', 10, 'US', 'iMessage', 739094400000000000, NULL, 739095000000000000, 1, 0, 1, 0, 0, 0),
  (46, 'GUID-MSG-0046', 'Any update on the permit desk?', 0, 'US', 'iMessage', 739098000000000000, 739099200000000000, 739098600000000000, 1, 1, 1, 1, 0, 0),
  (47, 'GUID-MSG-0047', 'The revised estimate is attached.', 11, 'US', 'iMessage', 739101600000000000, NULL, 739102200000000000, 1, 0, 1, 0, 0, 0),
  (48, 'GUID-MSG-0048', 'The crew is waiting on the permit.', 0, 'US', 'iMessage', 739105200000000000, 739106400000000000, 739105800000000000, 1, 1, 1, 1, 0, 0),
  (49, 'GUID-MSG-0049', 'Keep the gate locked after six.', 12, 'US', 'iMessage', 739108800000000000, NULL, 739109400000000000, 1, 0, 1, 0, 0, 0),
  (50, 'GUID-MSG-0050', 'The lot is full, park across the street.', 0, 'US', 'iMessage', 739112400000000000, 739113600000000000, 739113000000000000, 1, 1, 1, 1, 0, 0),
  (51, 'GUID-MSG-0051', 'The invoice is attached, approve it.', 12, 'US', 'iMessage', 739116000000000000, NULL, 739116600000000000, 1, 0, 1, 0, 0, 0);
